    left, right = data['base']
    if left >= right:
        return []

    blocked = data['blocked']
    result = []
    current_start = left

    for a, b in blocked:
        if a >= b:
            continue

        # Если блок полностью левее текущего интервала, пропускаем
        if b <= current_start:
            continue

        # Если блок полностью правее текущего интервала, переходим к нему
        if a >= right:
            break

        # Блок пересекается с текущим интервалом
        # Вырезаем часть до начала блока
        if current_start < a:
            result.append([current_start, a])
            current_start = a

        # Обновляем правую границу текущего интервала до конца блока
        if b > right:
            right = b
        else:
            # Блок внутри или частично внутри, но мы уже вырезали левую часть
            # Если блок полностью внутри текущего интервала (a >= current_start и b <= right),
            # то current_start становится b
            if a >= current_start:
                current_start = b

    # Добавляем оставшуюся часть, если она есть
    if current_start < right:
        result.append([current_start, right])

    return result"
